function sshLogic(h) {
  const { T, V, set, canWrite, D, owner } = h; const sp = (s) => { const q = String(s).split('|'); return T(q[0], q[1] === undefined ? q[0] : q[1]); };
  const flt = V._f ?? 0, open = V._o ?? -1, ran = V._ran ?? -1;
  const LN = [['Runs at once|即刻行', 'Reads only|淨係讀'], ['Preview first|先預覽', 'You see old and new values|先睇舊值同新值'], ['Preview and guard|預覽加守護', 'Rolls back if you lose the router|搵唔返路由器就回復'], ['Four keys|四條鎖匙', 'Owner only, never in Live mode|只限擁有人，Live 模式都唔得']];
  const KD = ['All|全部', 'Read|讀取', 'Change|更改', 'Restart|重啟', 'Dangerous|危險'];
  const acts = D.x.map((a, i) => ({ i, name: sp(a[0]), cmd: a[1], kind: a[2], lane: a[3], what: sp(a[4]), d: a[5], mad: a[6] }));
  const lanes = LN.map((l, li) => { const items = acts.filter(a => a.lane === li && (flt === 0 || a.kind === flt)).map((a, j) => ({ name: a.name, cmd: a.cmd, d: a.d, style: '--j:' + (li * 2 + j), cls: 'card' + (a.i === ran ? ' pick' : ''), ran: a.i === ran, open: () => set({ _o: a.i }) })); return { title: sp(l[0]), sub: sp(l[1]), items, n: items.length, none: items.length === 0, ic: li === 3 }; });
  const a = acts[open < 0 ? 0 : open];
  const cur = { name: a.name, cmd: a.cmd, what: a.what, d: a.d, lane: sp(LN[a.lane][0]), laneSub: sp(LN[a.lane][1]), mad: T('Level ' + a.mad, '第 ' + a.mad + ' 級'), madCls: a.mad >= 3 ? 'tag bad' : a.mad === 2 ? 'tag warn' : a.mad === 1 ? 'tag pri' : 'tag good',
    undo: a.kind === 1 ? T('Nothing to undo: it only reads.', '冇嘢要還原：淨係讀。') : a.kind === 4 ? T('Cannot be undone once it starts.', '一開始就還原唔到。') : T('Recorded in history; one tap puts it back.', '會記入記錄，㩒一下就放返。'),
    fourKey: a.lane === 3, canRun: a.lane !== 3, ownerOnly: a.lane === 3 && !owner, close: () => set({ _o: -1 }), run: () => { if (a.kind === 1 || canWrite) set({ _o: -1, _ran: a.i }); } };
  return { lanes, cur, sheet: open >= 0, filters: KD.map((k, i) => ({ label: sp(k), pressed: flt === i ? 'true' : 'false', pick: () => set({ _f: i }) })), toast: ran >= 0, toastText: ran >= 0 ? acts[ran].name + ': ' + T('ran on the router and was recorded in history.', '已經喺路由器行咗，亦記入咗記錄。') : '', toastCmd: ran >= 0 ? acts[ran].cmd : '', clearToast: () => set({ _ran: -1 }), shown: acts.filter(z => flt === 0 || z.kind === flt).length };
}

