// ---- firmware upload
function uploadLogic(h) {
  const { T, V, set, canWrite } = h;
  const step = V._s ?? 3;
  const STEPS = [T('Choose the file', '揀檔案'), T('Five checks', '五項檢查'), T('Four keys', '四條鎖匙'), T('Writing: the dim sum moment', '寫入：飲茶時間'), T('Back online', '返返嚟')];
  const CH = [[T('Made for this model', '係咪呢個型號嘅檔案'), 'RT-AX86U'], [T('Checksum matches the published one', '校驗碼同公佈嗰個一樣'), 'SHA-256 9f3c ... 41ab'], [T('Signature is valid', '簽署有效'), T('Signed by the firmware developer', '由韌體開發者簽署')], [T('Not older than what is installed', '唔會舊過而家裝緊嗰個'), '388.8_2 > 388.8_4'], [T('Settings backed up first', '已經先備份設定'), T('412 settings saved on this computer', '412 項設定已儲存喺呢部電腦')]];
  const go = (n) => () => { if (canWrite) set({ _s: n }); };
  const buns = step >= 4 ? 5 : step === 3 ? 3 : 0;
  return { step, s0: step === 0, hasFile: step >= 1, canCheck: step === 1, canFlash: step === 2, flashing: step === 3, back: step === 4, before: step < 3, moment: step >= 3,
    pipe: STEPS.map((s, i) => ({ label: s, n: i + 1, hasPc: i > 0, pcCls: 'pc ' + (i < step ? 'done' : i === step ? 'now' : ''), psCls: 'ps ' + (i < step ? 'done' : i === step ? 'now' : ''), isDone: i < step, notDone: i >= step })),
    checks: CH.map((c, j) => ({ name: c[0], det: c[1], style: '--j:' + j, tag: step >= 2 ? T('Passed', '通過') : step === 1 ? T('Waiting', '等緊') : T('No file yet', '未有檔案'), tagCls: step >= 2 ? 'tag good' : 'tag' })),
    buns: [0, 1, 2, 3, 4].map(k => ({ cls: 'bun' + (k < buns ? ' dr' : ' todo'), style: '--k:' + k })), bunsDone: buns,
    pick: go(1), check: go(2), flash: go(3), online: go(4), reset: go(0), pct: step >= 4 ? 100 : 62 };
}
