// ---- Live mode: [name, where, icon, starting value]
const LIVE = [['Guest Wi-Fi|訪客 Wi-Fi', 'Wi-Fi', 'wifi', 0], ['Status lights|狀態燈', 'System|系統', 'sun', 1], ['Pause internet for Alex-Tablet|暫停 Alex-Tablet 上網', 'Parental controls|家長控制', 'family', 0], ['WPS push button|WPS 按鈕', 'Wi-Fi', 'key', 0], ['Traffic priority|流量優先', 'Traffic priority|流量優先', 'qos', 1], ['UPnP port opening|UPnP 自動開端口', 'Firewall|防火牆', 'fwd', 1]];
